(() => {
'use strict';

const POLL_INTERVAL = 2000;
const TERMINAL_STATES = new Set(['complete', 'error', 'stopped']);

const $ = (selector) => document.querySelector(selector);

const els = {
    badge: $('#status-badge'),
    uploadZone: $('#upload-zone'),
    tracksView: $('#tracks-view'),
    dropzone: $('#dropzone'),
    pickBtn: $('#pick-btn'),
    fileInput: $('#file-input'),
    uploadProgress: $('#upload-progress'),
    uploadStatus: $('#upload-status'),
    uploadFill: $('#upload-fill'),
    processBtn: $('#process-btn'),
    stopBtn: $('#stop-btn'),
    queueCheck: $('#queue-check'),
    trackTotalText: $('#track-total-text'),
    progressFill: $('#progress-fill'),
    progressLabel: $('#progress-label'),
    banner: $('#banner'),
    bannerText: $('#banner-text'),
    bannerFoldersToggle: $('#banner-folders-toggle'),
    bannerFolders: $('#banner-folders'),
    tbody: $('#tracks-tbody'),
    logToggle: $('#log-toggle'),
    console: $('#console'),
};

const state = {
    rows: [],                 // строки из get_inbox
    rowRefs: new Map(),       // name -> {tr, nameCell, bpmCell, keyCell, durCell, playBtn, playWrapper, playFill, playTime, playBar}
    sort: {},                 // { key: 'num'|'track'|'bpm'|'key'|'duration', dir: 1|-1|0 }
    mode: 'idle',             // 'idle' | 'processing' | 'poll' | 'done'
    es: null,
    pollTimer: null,
    liveTimer: null,
    fallbackFired: false,
    stopping: false,
    renderedLogs: 0,
    play: { audio: null, name: null },
};

const api = { base: 'analysisApi.php' };

function fetchJson(action, options) {
    return fetch(`${api.base}?action=${encodeURIComponent(action)}`, options)
        .then(async (res) => {
            if (!res.ok) throw new Error(`HTTP ${res.status}`);
            return res.json();
        });
}

function fmtDuration(sec) {
    if (sec == null || !Number.isFinite(Number(sec))) return '—';
    const s = Math.round(Number(sec));
    const m = Math.floor(s / 60);
    const r = s % 60;
    return `${String(m).padStart(2, '0')}:${String(r).padStart(2, '0')}`;
}

function setBadge(status) {
    els.badge.dataset.state = status;
    els.badge.textContent = (status || 'idle').replace('_', ' ');
}

function appendLog(entry) {
    const { time, type, message } = entry || {};
    const row = document.createElement('div');
    row.className = 'log';

    const timeEl = document.createElement('span');
    timeEl.className = 'time';
    timeEl.textContent = time || '--:--:--';

    const badgeEl = document.createElement('span');
    badgeEl.className = `badge badge-${['info', 'success', 'error', 'warning'].includes(type) ? type : 'info'}`;
    badgeEl.textContent = (type || 'info').toUpperCase();

    const msgEl = document.createElement('span');
    msgEl.textContent = message;

    row.append(timeEl, badgeEl, msgEl);
    els.console.appendChild(row);
    els.console.scrollTop = els.console.scrollHeight;

    if (type === 'error' && els.console.hidden) toggleLog(true);
}

function renderLogs(logs = []) {
    for (let i = state.renderedLogs; i < logs.length; i++) appendLog(logs[i]);
    state.renderedLogs = Math.max(state.renderedLogs, logs.length);
}

function updateOverall(processed, total) {
    const t = total ?? 0;
    const d = processed ?? 0;
    const percent = t > 0 ? Math.min(100, Math.round((d / t) * 100)) : 0;

    els.progressFill.style.width = `${percent}%`;
    els.progressLabel.textContent = t > 0 ? `${percent}% · ${d}/${t}` : '0%';
    els.progressFill.classList.toggle('is-running', state.mode === 'processing');
}

function buildNameNode(row) {
    const wrap = document.createElement('div');
    wrap.className = 'name-stack';

    const line1 = document.createElement('span');
    line1.className = 'track-title';
    line1.textContent = row.title || row.name;

    const line2 = document.createElement('span');
    line2.className = 'track-artist';
    line2.textContent = `${row.artist || 'Неизвестен'} · ${row.name}`;

    wrap.append(line1, line2);
    return wrap;
}

function toggleLog(force) {
    const show = typeof force === 'boolean' ? force : els.console.hidden;
    els.console.hidden = !show;
    els.logToggle.classList.toggle('is-open', show);
    if (show) els.console.scrollTop = els.console.scrollHeight;
}

// ---------- Плеер ----------

function fmtMinSec(sec) {
    const s = Math.max(0, Math.floor(Number(sec) || 0));
    return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

function initPlayer() {
    const audio = new Audio();
    audio.preload = 'metadata';
    state.play.audio = audio;

    audio.addEventListener('play', () => setPlayGlyph(state.play.name, 'pause'));
    audio.addEventListener('pause', () => setPlayGlyph(state.play.name, 'play'));
    audio.addEventListener('loadedmetadata', () => updatePlayBar());
    audio.addEventListener('ended', () => {
        if (els.queueCheck.checked && playNextInQueue()) {
            return;
        }
        setPlayGlyph(state.play.name, 'play');
        resetPlayBar(state.play.name);
        state.play.name = null;
    });
    audio.addEventListener('error', () => {
        setPlayGlyph(state.play.name, 'play');
        state.play.name = null;
    });
    audio.addEventListener('timeupdate', () => updatePlayBar());
}

function buildPlayButton(name) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'play-btn';
    btn.dataset.name = name;
    btn.title = 'Прослушать';

    const glyph = document.createElement('span');
    glyph.className = 'play-glyph';
    const pause = document.createElement('span');
    pause.className = 'play-pause';
    pause.append(document.createElement('span'), document.createElement('span'));
    btn.append(glyph, pause);

    btn.addEventListener('click', (e) => {
        e.stopPropagation();
        togglePlay(name);
    });
    return btn;
}

function togglePlay(name) {
    const audio = state.play.audio;
    if (!audio) return;

    if (state.play.name === name && audio.src !== '') {
        if (audio.paused) audio.play().catch(() => {});
        else audio.pause();
        return;
    }

    if (state.play.name && state.play.name !== name) {
        setPlayGlyph(state.play.name, 'play');
        resetPlayBar(state.play.name);
    }

    const url = `../music/inbox/${encodeURIComponent(name)}`;
    state.play.name = name;
    audio.src = url;
    audio.play().catch((err) => {
        appendLog({ time: '--:--:--', type: 'error', message: `Не удалось проиграть «${name}»: ${err.message || 'ошибка источника'}` });
        setPlayGlyph(name, 'play');
    });
}

function setPlayGlyph(name, mode) {
    const ref = state.rowRefs.get(name);
    if (!ref || !ref.playBtn) return;
    ref.playBtn.classList.toggle('is-playing', mode === 'pause');
    ref.playBtn.title = mode === 'pause' ? 'Пауза' : 'Прослушать';
}

function resetPlayBar(name) {
    const ref = state.rowRefs.get(name);
    if (!ref || !ref.playFill) return;
    ref.playFill.style.width = '0%';
    ref.playTime.textContent = '';
}

function updatePlayBar() {
    const audio = state.play.audio;
    const name = state.play.name;
    const ref = audio && state.rowRefs.get(name);
    if (!ref || !ref.playFill) return;

    const dur = audio.duration;
    const cur = audio.currentTime || 0;
    if (dur && Number.isFinite(Number(dur))) {
        ref.playFill.style.width = `${Math.min(100, (cur / dur) * 100)}%`;
        ref.playTime.textContent = `${fmtMinSec(cur)} / ${fmtMinSec(dur)}`;
    } else {
        ref.playFill.style.width = '0%';
        ref.playTime.textContent = `${fmtMinSec(cur)}`;
    }
}

function bindSeek(bar, name) {
    let seeking = false;
    const seekTo = (e) => {
        const audio = state.play.audio;
        if (!audio || state.play.name !== name) return;
        const dur = audio.duration;
        if (!dur || !Number.isFinite(Number(dur))) return;
        const rect = bar.getBoundingClientRect();
        const frac = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width));
        audio.currentTime = frac * dur;
        const ref = state.rowRefs.get(name);
        if (ref) {
            ref.playFill.style.width = `${frac * 100}%`;
            ref.playTime.textContent = `${fmtMinSec(frac * dur)} / ${fmtMinSec(dur)}`;
        }
    };
    bar.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        seeking = true;
        bar.setPointerCapture(e.pointerId);
        seekTo(e);
    });
    bar.addEventListener('pointermove', (e) => {
        if (seeking) seekTo(e);
    });
    const stop = () => { seeking = false; };
    bar.addEventListener('pointerup', stop);
    bar.addEventListener('pointercancel', stop);
}

function applyPlaybackState() {
    if (!state.play.name) return;
    const audio = state.play.audio;
    if (!audio || audio.paused) return;
    const ref = state.rowRefs.get(state.play.name);
    if (!ref) return;
    setPlayGlyph(state.play.name, 'pause');
    updatePlayBar();
}

// «Подряд»: по окончании трека включаем следующий из текущего порядка списка.
function playNextInQueue() {
    const list = state.rows.map((r) => r.name);
    if (list.length === 0) return false;
    const cur = list.indexOf(state.play.name);
    const next = cur >= 0 ? list[(cur + 1) % list.length] : list[0];
    togglePlay(next);
    return true;
}

// ---------- Отрисовка таблицы ----------

function renderTable(rows) {
    els.tbody.innerHTML = '';
    state.rowRefs.clear();

    rows.forEach((row, i) => {
        const tr = document.createElement('tr');

        const numCell = document.createElement('td');
        numCell.className = 'col-num';
        numCell.textContent = String(i + 1);

        const nameCell = document.createElement('td');
        nameCell.className = 'col-track';

        const playBtn = buildPlayButton(row.name);

        const playWrapper = document.createElement('div');
        playWrapper.className = 'play-wrap';
        const playFill = document.createElement('div');
        playFill.className = 'play-fill';
        const playBar = document.createElement('div');
        playBar.className = 'play-bar';
        playBar.appendChild(playFill);
        const playTime = document.createElement('span');
        playTime.className = 'play-time';
        playWrapper.append(playBar, playTime);

        bindSeek(playBar, row.name);

        const stack = document.createElement('div');
        stack.className = 'name-stack';
        stack.append(buildNameNode(row));
        stack.appendChild(playWrapper);

        nameCell.append(playBtn, stack);

        const bpmCell = document.createElement('td');
        bpmCell.className = 'col-center';
        bpmCell.textContent = row.bpm != null ? row.bpm : '—';

        const keyCell = document.createElement('td');
        keyCell.className = 'col-center';
        keyCell.textContent = row.key || '—';

        const durCell = document.createElement('td');
        durCell.className = 'col-center';
        durCell.textContent = fmtDuration(row.duration);

        if (row.status === 'error') tr.classList.add('row-error');
        if (row.status === 'done') tr.classList.add('row-done');

        tr.append(numCell, nameCell, bpmCell, keyCell, durCell);
        els.tbody.appendChild(tr);

        state.rowRefs.set(row.name, {
            tr, nameCell, bpmCell, keyCell, durCell, row,
            playBtn, playWrapper, playFill, playTime, playBar,
        });
    });

    els.trackTotalText.textContent = `Треков: ${rows.length}`;
    updateSortInd();
    applyPlaybackState();
}

function updateSortInd() {
    document.querySelectorAll('th[data-sort]').forEach((th) => {
        const ind = th.querySelector('.sort-ind');
        const key = th.dataset.sort;
        if (!ind) return;
        if (state.sort.key === key) {
            ind.textContent = state.sort.dir === 1 ? '▲' : state.sort.dir === -1 ? '▼' : '⇄';
            th.classList.add('is-sorted');
        } else {
            ind.textContent = '';
            th.classList.remove('is-sorted');
        }
    });
}

// ---------- Обновление строк в реальном времени ----------

function rowProcessing(name) {
    const ref = state.rowRefs.get(name);
    if (!ref || state.stopping) return;

    ref.tr.classList.remove('row-done', 'row-error');
    ref.tr.classList.add('row-processing');

    const barRow = document.createElement('div');
    barRow.className = 'cell-progress';
    const bar = document.createElement('div');
    bar.className = 'cell-fill';
    bar.style.width = '2%';
    barRow.appendChild(bar);

    const status = document.createElement('span');
    status.className = 'cell-status';
    status.textContent = 'Загрузка · 0%';

    const stack = document.createElement('div');
    stack.className = 'name-stack';
    stack.append(buildNameNode(ref.row), barRow, status, ref.playWrapper);

    ref.nameCell.replaceChildren(ref.playBtn, stack);

    ref.barEl = bar;
    ref.statusEl = status;
    ref.bpmCell.textContent = '—';
    ref.keyCell.textContent = '—';
    ref.durCell.textContent = '—';
}

function rowProgress(name, data) {
    const ref = state.rowRefs.get(name);
    if (!ref || !ref.barEl || state.stopping) return;

    const pct = Math.round((Number(data.progress) || 0) * 100);
    ref.barEl.style.width = `${Math.min(100, Math.max(0, pct))}%`;
    ref.statusEl.textContent = `${data.phase || 'Анализ'} · ${pct}%`;
}

function rowDone(name, result) {
    const ref = state.rowRefs.get(name);
    if (!ref) return;

    ref.tr.classList.remove('row-processing', 'row-error');
    ref.tr.classList.add('row-done');

    const doneChip = document.createElement('span');
    doneChip.className = 'chip chip-ok';
    doneChip.textContent = '✓ обработан';

    const stack = document.createElement('div');
    stack.className = 'name-stack';
    stack.append(buildNameNode(ref.row), doneChip, ref.playWrapper);
    ref.nameCell.replaceChildren(ref.playBtn, stack);

    ref.bpmCell.textContent = result.bpm ?? '—';
    ref.keyCell.textContent = result.key || '—';
    ref.durCell.textContent = fmtDuration(result.duration);
}

function rowError(name, message) {
    const ref = state.rowRefs.get(name);
    if (!ref) return;

    ref.tr.classList.remove('row-processing', 'row-done');
    ref.tr.classList.add('row-error');
    ref.durCell.textContent = '—';

    const chip = document.createElement('span');
    chip.className = 'chip chip-err';
    chip.textContent = '✕ ошибка';
    if (message) chip.title = message;

    const stack = document.createElement('div');
    stack.className = 'name-stack';
    stack.append(buildNameNode(ref.row), chip, ref.playWrapper);
    ref.nameCell.replaceChildren(ref.playBtn, stack);
}

function rebuildRowIdle(ref) {
    const stack = document.createElement('div');
    stack.className = 'name-stack';
    stack.append(buildNameNode(ref.row));
    stack.appendChild(ref.playWrapper);
    ref.nameCell.replaceChildren(ref.playBtn, stack);
}

// ---------- Сортировка по заголовкам колонок ----------

function sortBy(key) {
    if (state.mode === 'processing' || state.mode === 'poll') return;

    if (key === 'track') {
        state.rows = shuffle(state.rows);
        state.sort = { key: 'track', dir: 0 };
        renderTable(state.rows);
        return;
    }

    if (state.sort.key === key) {
        state.sort.dir = state.sort.dir === 1 ? -1 : 1;
    } else {
        state.sort = { key, dir: 1 };
    }

    const dir = state.sort.dir;
    const rows = [...state.rows].sort((a, b) => {
        let v = 0;
        switch (key) {
            case 'num':
                v = String(a.name).localeCompare(String(b.name), 'ru');
                break;
            case 'bpm':
                v = (a.bpm ?? -1) - (b.bpm ?? -1);
                break;
            case 'key':
                v = String(a.key || '').localeCompare(String(b.key || ''), 'ru');
                break;
            case 'duration':
                v = (a.duration ?? -1) - (b.duration ?? -1);
                break;
        }
        return v * dir;
    });

    state.rows = rows;
    renderTable(rows);
}

function shuffle(items) {
    const arr = [...items];
    for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
}

// ---------- Состояния-вью ----------

function switchToUpload() {
    els.uploadZone.hidden = false;
    els.tracksView.hidden = true;
    els.processBtn.disabled = true;
    setBadge('idle');
}

function switchToTracks(rows) {
    els.uploadZone.hidden = true;
    els.tracksView.hidden = false;
    renderTable(rows);
    const active = state.mode === 'processing' || state.mode === 'poll';
    els.processBtn.disabled = active;
    els.stopBtn.hidden = !active;
}

function showBanner(text, folders) {
    els.banner.hidden = false;
    els.bannerText.textContent = text;

    els.bannerFoldersToggle.hidden = !(folders && folders.length > 0);
    els.bannerFolders.innerHTML = '';

    if (folders && folders.length > 0) {
        folders.forEach((folder) => {
            const dir = document.createElement('div');
            dir.className = 'dir';
            dir.textContent = `music/sorted/${folder.name}/`;
            const sub = document.createElement('ul');
            (folder.files || []).forEach((f) => {
                const li = document.createElement('li');
                li.className = 'file';
                li.textContent = f;
                sub.appendChild(li);
            });
            dir.appendChild(sub);
            els.bannerFolders.appendChild(dir);
        });
    }
}

function hideBanner() {
    els.banner.hidden = true;
}

// ---------- Загрузка файлов ----------

function uploadFiles(files) {
    if (!files || files.length === 0) return;

    els.uploadProgress.hidden = false;
    els.uploadStatus.textContent = `Загрузка ${files.length} файл(ов)…`;

    const fd = new FormData();
    Array.from(files).forEach((f) => fd.append('files[]', f));

    fetchJson('upload', { method: 'POST', body: fd })
        .then(async (res) => {
            els.uploadFill.style.width = '100%';
            const uploaded = (res.uploaded || []).length;
            const rejected = res.rejected || [];
            els.uploadStatus.textContent = uploaded > 0
                ? `Загружено: ${uploaded}`
                : 'Ничего не загружено';

            rejected.forEach((r) => appendLog({ time: '--:--:--', type: 'warning', message: `${r.name}: ${r.reason}` }));

            if (uploaded > 0) {
                appendLog({ time: '--:--:--', type: 'info', message: `Загружено файлов: ${uploaded}` });
            }

            await refreshInbox();
        })
        .catch((err) => {
            els.uploadStatus.textContent = 'Ошибка загрузки';
            appendLog({ time: '--:--:--', type: 'error', message: `Загрузка не удалась: ${err.message}` });
        })
        .finally(() => {
            setTimeout(() => {
                els.uploadProgress.hidden = true;
                els.uploadFill.style.width = '0%';
            }, 1500);
            els.fileInput.value = '';
        });
}

function refreshInbox() {
    return fetchJson('get_inbox')
        .then((data) => {
            state.rows = data.rows || [];
            state.sort = {};
            if (state.rows.length === 0) {
                switchToUpload();
            } else {
                switchToTracks(state.rows);
            }
        })
        .catch(() => appendLog({ time: '--:--:--', type: 'error', message: 'Не удалось получить список треков.' }));
}

function bindUpload() {
    const openPicker = () => els.fileInput.click();

    els.pickBtn.addEventListener('click', openPicker);
    els.dropzone.addEventListener('click', openPicker);

    els.dropzone.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') openPicker();
    });

    els.fileInput.addEventListener('change', () => uploadFiles(els.fileInput.files));

    ['dragenter', 'dragover'].forEach((ev) =>
        els.dropzone.addEventListener(ev, (e) => {
            e.preventDefault();
            els.dropzone.classList.add('dz-over');
        })
    );
    ['dragleave', 'drop'].forEach((ev) =>
        els.dropzone.addEventListener(ev, (e) => {
            e.preventDefault();
            els.dropzone.classList.remove('dz-over');
        })
    );
    els.dropzone.addEventListener('drop', (e) => uploadFiles(e.dataTransfer.files));
}

// ---------- SSE-поток ----------

function startProcessing() {
    state.mode = 'processing';
    state.fallbackFired = false;
    state.stopping = false;
    stopPolling();
    closeStream();

    els.processBtn.disabled = true;
    els.stopBtn.hidden = false;
    hideBanner();
    els.console.innerHTML = '';
    state.renderedLogs = 0;
    setBadge('running');
    updateOverall(0, state.rows.length);

    // сбрасываем все строки в «ожидание»
    state.rowRefs.forEach((ref) => {
        ref.tr.classList.remove('row-done', 'row-error', 'row-processing');
        rebuildRowIdle(ref);
        ref.bpmCell.textContent = '—';
        ref.keyCell.textContent = '—';
        ref.durCell.textContent = '—';
    });

    const es = new EventSource(`${api.base}?action=stream_analyze`);
    state.es = es;

    const events = {
        log: (d) => appendLog(d),
        progress: (d) => updateOverall(d.processed, d.total),
        track_start: (d) => rowProcessing(d.name),
        track_progress: (d) => rowProgress(d.name, d),
        track_done: (d) => rowDone(d.name, d),
        track_error: (d) => rowError(d.name, d.message),
        idle: (d) => {
            appendLog({ time: '--:--:--', type: 'warning', message: d.message || 'Нет файлов для обработки.' });
            finishProcessing('idle');
        },
        already_running: (d) => {
            appendLog({ time: '--:--:--', type: 'warning', message: d.message || 'Анализ уже выполняется в другом окне.' });
            closeStream();
            startPolling(false);
        },
        done: (d) => {
            const wasStopped = d && d.status === 'stopped';
            updateOverall(wasStopped ? (d.processed ?? 0) : d.total, d.total);
            const message = wasStopped
                ? `Остановлено: обработано ${d.sorted ?? 0} из ${d.total ?? 0} файлов.`
                : `Готово: обработано ${d.sorted ?? 0} из ${d.total ?? 0} файлов.`;
            showBanner(message, d.folders || []);
            appendLog({ time: '--:--:--', type: 'info', message });
            finishProcessing(wasStopped ? 'stopped' : 'complete');
            refreshInbox();
        },
        error: (d) => {
            appendLog({ time: '--:--:--', type: 'error', message: d.message || 'Ошибка сервера.' });
            finishProcessing('error');
        },
    };

    Object.entries(events).forEach(([name, handler]) =>
        es.addEventListener(name, (e) => {
            try { handler(JSON.parse(e.data)); } catch { /* повреждённое событие */ }
        })
    );

    es.onerror = () => fallbackToPolling();

    // Страховка на случай буферизации стрима: полоса и статус всё равно
    // двигаются из progress.json, который сервер пишет параллельно циклу.
    startLivePoll();
}

function fallbackToPolling() {
    if (state.mode !== 'processing') return;
    appendLog({ time: '--:--:--', type: 'warning', message: 'Поток реального времени прервался, переключаюсь на опрос…' });
    startPolling(true);
}

function finishProcessing(status) {
    closeStream();
    stopPolling();
    stopLivePoll();
    state.mode = 'done';
    state.stopping = false;
    els.processBtn.disabled = false;
    els.stopBtn.hidden = true;
    setBadge(status); // complete/error/idle/stopped — все терминальные состояния подсвечиваем
}

function closeStream() {
    if (state.es) {
        state.es.close();
        state.es = null;
    }
}

// ---------- Живой опрос прогресса (страховка от буферизации SSE) ----------

function startLivePoll() {
    stopLivePoll();
    state.liveTimer = setInterval(pollLive, 500);
}

function stopLivePoll() {
    if (state.liveTimer !== null) {
        clearInterval(state.liveTimer);
        state.liveTimer = null;
    }
}

function pollLive() {
    if (state.mode !== 'processing') {
        stopLivePoll();
        return;
    }

    fetchJson('get_progress')
        .then((p) => {
            if (state.mode !== 'processing') return;

            const status = p.status || 'idle';
            if (TERMINAL_STATES.has(status)) {
                stopLivePoll();
                return;
            }

            updateOverall(p.processed, p.total);
            renderLogs(p.log || []);

            const live = p.live;
            if (live && live.name) {
                rowProgress(live.name, live);
            } else if (p.current_file) {
                rowProcessing(p.current_file);
            }
        })
        .catch(() => {});
}

// ---------- Остановка анализа ----------

function requestStop() {
    state.stopping = true;
    els.stopBtn.disabled = true;
    els.stopBtn.textContent = 'Останавливаю…';

    appendLog({ time: '--:--:--', type: 'warning', message: 'Запрошена остановка: завершаю текущий трек…' });

    fetchJson('stop_analysis')
        .then(() => {
            // Истинное завершение придёт событием done(status: stopped)
            // либо терминальным состоянием через опрос.
        })
        .catch((err) => {
            els.stopBtn.disabled = false;
            els.stopBtn.textContent = '■ Стоп';
            appendLog({ time: '--:--:--', type: 'error', message: `Не удалось остановить: ${err.message}` });
        });
}

// ---------- Фолбэк: опрос ----------

function startPolling(launchAnalysis) {
    stopPolling();
    state.mode = 'poll';
    els.processBtn.disabled = true;
    els.stopBtn.hidden = false;

    if (launchAnalysis && !state.fallbackFired) {
        state.fallbackFired = true;
        fetchJson('analyze_inbox').catch(() => {});
    }

    state.pollTimer = setInterval(pollProgress, POLL_INTERVAL);
    pollProgress();
}

function stopPolling() {
    if (state.pollTimer !== null) {
        clearInterval(state.pollTimer);
        state.pollTimer = null;
    }
}

function pollProgress() {
    fetchJson('get_progress')
        .then((progress) => {
            const status = progress.status || 'idle';
            setBadge(status);
            updateOverall(progress.processed, progress.total);
            renderLogs(progress.log || []);

            if (status === 'running') {
                const live = progress.live;
                if (live && live.name) {
                    rowProgress(live.name, live);
                } else {
                    const cur = progress.current_file;
                    state.rowRefs.forEach((ref, name) => {
                        if (cur && name === cur) rowProcessing(name);
                    });
                }
                return;
            }

            if (TERMINAL_STATES.has(status)) {
                stopPolling();
                els.processBtn.disabled = false;
                els.stopBtn.hidden = true;
                state.mode = 'done';
                updateOverall(progress.processed, progress.total);

                if (status === 'complete') {
                    showBanner('Анализ завершён.', progress.folders || []);
                    refreshInbox();
                } else if (status === 'stopped') {
                    showBanner('Анализ остановлен.', progress.folders || []);
                    refreshInbox();
                }
            }
        })
        .catch(() => {
            stopPolling();
            state.mode = 'idle';
            els.processBtn.disabled = false;
        });
}

// ---------- Инициализация ----------

function init() {
    bindUpload();
    initPlayer();
    els.logToggle.addEventListener('click', () => toggleLog());
    els.bannerFoldersToggle.addEventListener('click', () => {
        els.bannerFolders.hidden = !els.bannerFolders.hidden;
        els.bannerFoldersToggle.textContent = els.bannerFolders.hidden ? 'Папки ▾' : 'Папки ▴';
    });

    els.processBtn.addEventListener('click', startProcessing);
    els.stopBtn.addEventListener('click', requestStop);

    document.querySelectorAll('th[data-sort]').forEach((th) =>
        th.addEventListener('click', () => sortBy(th.dataset.sort))
    );

    Promise.all([
        fetchJson('get_inbox'),
        fetchJson('get_progress'),
    ])
        .then(([inbox, progress]) => {
            setBadge(progress.status || 'idle');

            if (inbox.rows && inbox.rows.length === 0) {
                switchToUpload();
                return;
            }

            state.rows = inbox.rows;
            switchToTracks(state.rows);
            renderLogs(progress.log || []);

            if (progress.status === 'running') {
                // в другом окне уже идёт обработка — просто следуем
                appendLog({ time: '--:--:--', type: 'warning', message: 'Обнаружен идущий анализ (другое окно). Слежу за прогрессом.' });
                startPolling(false);
            } else if (TERMINAL_STATES.has(progress.status)) {
                if (progress.status === 'complete' && inbox.rows.length > 0) {
                    showBanner(`Последний прогон: ${progress.log.length > 0 ? 'завершён.' : ''}`, progress.folders || []);
                }
            }
        })
        .catch(() => {
            switchToUpload();
        });
}

document.addEventListener('DOMContentLoaded', init);
})();
